mapper.select:
SELECT t.id, t.tx_no, t.tx_type, t.warehouse_id, w.name AS warehouse_name, t.location_id, l.code AS location_code, t.sku_id, p.sku_code, p.name AS sku_name, t.batch_no, t.qty_change, t.locked_change, t.frozen_change, t.qty_before, t.qty_after, t.source_type, t.source_id, t.source_no, t.operator_id, t.operator_name, t.remark, t.create_time FROM inventory_transaction t LEFT JOIN warehouse w ON w.id = t.warehouse_id AND w.deleted = 0 LEFT JOIN location l ON l.id = t.location_id LEFT JOIN product p ON p.id = t.sku_id WHERE 1 = 1
AND (t.tx_no LIKE CONCAT('%', #{query.keyword}, '%') OR p.sku_code LIKE CONCAT('%', #{query.keyword}, '%') OR p.name LIKE CONCAT('%', #{query.keyword}, '%'))
AND t.tx_type = #{query.txType}
AND t.sku_id = #{query.skuId}
AND t.location_id = #{query.locationId}
AND t.source_no = #{query.sourceNo}
AND t.create_time >= #{query.beginTime}
AND t.create_time < DATE_ADD(#{query.endTime}, INTERVAL 1 DAY)
ORDER BY t.id DESC
